15	#ifndef TESTS_VERILATOR_SIM_CORALNPU_MEMORY_IF_H_
16	#define TESTS_VERILATOR_SIM_CORALNPU_MEMORY_IF_H_
17	
18	#include <stdint.h>
19	#include <stdio.h>
20	
21	#include <algorithm>
22	#include <map>
23	
24	#include "tests/verilator_sim/sysc_module.h"
25	
26	// A memory model base class
27	struct Memory_if : Sysc_module {
28	  const int kPageSize = 4 * 1024;
29	  const int kPageMask = ~(kPageSize - 1);
30	
31	  struct memory_page_t {
32	    uint32_t addr;
33	    uint8_t  data[4096];
34	  };
35	
36	  Memory_if(sc_module_name n, const char* bin, int limit = -1) :
37	      Sysc_module(n) {
38	    FILE *f = fopen(bin, "rb");
39	
40	    fseek(f, 0, SEEK_END);
41	    int64_t fsize = ftell(f);
42	    fseek(f, 0, SEEK_SET);
43	    uint8_t *fdata = new uint8_t[fsize];
44	
45	    fread(fdata, fsize, 1, f);
46	    fclose(f);
47	
48	    if (limit > 0 && fsize > limit) {
49	      printf("***ERROR Memory_if limit exceeded [%ld > %d]\n", fsize, limit);
50	      exit(-1);
51	    }
52	
53	    int addr = 0;
54	    for (; addr < fsize; addr += kPageSize) {
55	      const int64_t size = std::min(fsize - addr, int64_t(kPageSize));
56	      AddPage(addr, size, fdata + addr);
57	    }
58	    // Create pages for the rest of our memory space, that was not created
59	    // for inserting the binary.
60	    for (; addr < 0x400000; addr += kPageSize) {
61	      AddPage(addr, kPageSize, nullptr);
62	    }
63	
64	    delete [] fdata;
65	  }
66	
67	  bool Read(uint32_t addr, int bytes, uint8_t* data) {
68	    while (bytes > 0) {
69	      const uint32_t maddr = addr & kPageMask;
70	      const uint32_t offset = addr - maddr;
71	      const int limit = kPageSize - offset;
72	      const int len = std::min(bytes, limit);
73	
