126	  void ReadSwizzle(const uint32_t addr, const int bytes, uint8_t* data) {
127	    const int mask = bytes - 1;
128	    const int alignment = (bytes - (addr & mask)) & mask;  // left shuffle
129	    uint8_t tmp[512/8];
130	
131	    if (!alignment) return;
132	
133	    for (int i = 0; i < bytes; ++i) {
134	      tmp[i] = data[i];
